def admit(active, waiting, budget, slots):
    # Validate oversized reservations against total budget
    for v in waiting:
        if v > budget:
            raise ValueError("reservation exceeds total budget")

    used_budget = sum(active)
    used_slots = len(active)

    admitted = []
    for v in waiting:
        if used_budget + v > budget:
            break
        if used_slots + 1 > slots:
            break
        admitted.append(v)
        used_budget += v
        used_slots += 1

    remaining = waiting[len(admitted):]
    return admitted, remaining

def endpoint(base_url, path):
    base = base_url.rstrip('/')
    if base.endswith('/v1'):
        return base + '/' + path.lstrip('/')
    else:
        return base + '/v1/' + path.lstrip('/')

